(OUT/'deck-content.json').write_text(json.dumps({'slides':slides,'main_word_count':word_count,'font':'Arial','main_slides':22},indent=2))
script=['# English presentation script','',f'22 main slides, a 4:06 video, Questions, and {len(slides)-23} backup slides.','',f'Spoken main-note text: approximately {word_count} words. The playback instruction is not spoken.','',f'At 150 words/min: approximately {word_count/150+4.1:.1f} minutes plus slide transitions. At 160: {word_count/160+4.1:.1f} minutes. Rehearse before relying on these estimates.','']
for s in slides:
 script += [f'## {s["number"]:02d}. {s["title"].replace(chr(10)," ")}', '',s['notes'],'','Sources: '+', '.join(s['sources']),'']
(ROOT/'reports/presentation/speaker-script-final.md').write_text('\n'.join(script))
